def _tem_descricao_legada(registro):
    """Identifica somente TEXTO livre, sem interpretar medidas clinicas."""
    import unicodedata
    for chave, valor in registro.items():
        if not isinstance(valor, str) or not valor.strip():
            continue
        nome = unicodedata.normalize('NFKD', chave.lower())
        nome = ''.join(c for c in nome if not unicodedata.combining(c))
        if ('descri' in nome or 'observac' in nome or
                'instru' in nome or 'anotac' in nome):
            return True
    return False


def _campos_objeto(pai):
    # Preserva o nome real de cada coluna, identificando a tabela de origem.
    return {'objeto_' + k: v for k, v in pai.items()
            if k not in ('id_objeto', 'id_ordem_servico')}


def dados_opticos_completos(con, number):
    """Consulta tabelas de optica e os cadastros antigos SOMENTE com SELECT.

    Em backups antigos, a receita podia estar em uma descricao livre do objeto,
    sem registro na tabela de medidas. Esses objetos devem aparecer tambem.
    """
    cols = _optical_columns(con, 'objeto_ordem_servico_oticas')
    result = []
    if 'id_ordem_servico' in cols:
        select_cols = ','.join(_optical_sql_name(c) for c in cols)
        order = '[id_objeto]' if 'id_objeto' in cols else '[id_ordem_servico]'
        result = run(con, f"""SELECT TOP (100) {select_cols}
            FROM dbo.objeto_ordem_servico_oticas
            WHERE id_ordem_servico=? ORDER BY {order}""", (number,))

    parent_cols = _optical_columns(con, 'objeto_ordem_servico')
    if not parent_cols:
        return result

    parents = []
    if 'id_ordem_servico' in parent_cols:
        # Busca por OS, inclusive se a tabela de receita estruturada estiver vazia.
        select_parent = ','.join(_optical_sql_name(c) for c in parent_cols)
        order = '[id_objeto]' if 'id_objeto' in parent_cols else '[id_ordem_servico]'
        parents = run(con, f"""SELECT TOP (100) {select_parent}
            FROM dbo.objeto_ordem_servico WHERE id_ordem_servico=?
            ORDER BY {order}""", (number,))
    elif 'id_objeto' in parent_cols:
        # Compatibilidade: bancos onde o objeto nao tem chave direta da OS.
        select_parent = ','.join(_optical_sql_name(c) for c in parent_cols)
        keys = {r.get('id_objeto') for r in result if r.get('id_objeto') is not None}
        for obj_id in keys:
            parents.extend(run(con, f"""SELECT TOP (1) {select_parent}
                FROM dbo.objeto_ordem_servico WHERE id_objeto=?""", (obj_id,)))

    optical_by_id = {r.get('id_objeto'): r for r in result
                     if r.get('id_objeto') is not None}
    for parent in parents:
        obj_id = parent.get('id_objeto')
        target = optical_by_id.get(obj_id) if obj_id is not None else None
        if target is not None:
            # Medidas e descricao pertencem ao mesmo objeto, sem duplicar receita.
            for key, value in _campos_objeto(parent).items():
                target.setdefault(key, value)
        elif _tem_descricao_legada(parent):
            # Descricao avulsa antiga: recuperar sem inventar esferico, eixo, etc.
            record = {'id_objeto': obj_id, '_receita_legada': True}
            record.update(_campos_objeto(parent))
            result.append(record)
    return result

