# Resolve nomes faltantes, usando IDs originais; nao altera OS/entidade.
_CLIENT_NAME_FIELDS = (
    'nome_razao_social', 'nome_completo', 'nome', 'razao_social',
    'nome_fantasia', 'nome_entidade', 'nome_cliente', 'nome_cadastro'
)
_CLIENT_TEXT_TYPES = frozenset(('nvarchar', 'varchar', 'char', 'nchar',
                                'text', 'ntext'))


def _preencher_nome_cliente(con, registros, campo='cliente'):
    """Complementa nomes em lote, sem modificar dados originais do Moderniza.

    Preserva sempre o nome da propria OS quando preenchido. Na ausencia,
    procura dbo.entidade pelo id exato; depois, outra OS com o mesmo id.
    """
    pendentes = {}
    for registro in registros:
        codigo = registro.get('id_cliente')
        nome = registro.get(campo)
        if codigo is not None and codigo != 0 and (
                nome is None or not str(nome).strip()):
            pendentes[codigo] = None
    if not pendentes:
        return registros

    codigos = list(pendentes)[:50]
    encontrados = {}
    placeholders = ','.join('?' for _ in codigos)
    try:
        meta = run(con, """SELECT c.name AS coluna, tp.name AS tipo
            FROM sys.columns c
            JOIN sys.tables t ON t.object_id=c.object_id
            JOIN sys.schemas s ON s.schema_id=t.schema_id
            JOIN sys.types tp ON tp.user_type_id=c.user_type_id
            WHERE s.name=N'dbo' AND t.name=N'entidade'""")
        cols = {r['coluna'].lower(): r['coluna'] for r in meta}
        tipos = {r['coluna'].lower(): str(r['tipo']).lower() for r in meta}
        campos = [cols[n] for n in _CLIENT_NAME_FIELDS
                  if n in cols and tipos[n] in _CLIENT_TEXT_TYPES]
        if 'id_entidade' in cols and campos:
            partes = [
                "NULLIF(LTRIM(RTRIM(CAST(e." + _optical_sql_name(c) +
                " AS NVARCHAR(300)))), N'')" for c in campos
            ]
            expressao = ('COALESCE(' + ','.join(partes) + ')'
                         if len(partes) > 1 else partes[0])
            dados = run(con, f"""SELECT
                    e.{_optical_sql_name(cols['id_entidade'])}
                    AS id_cliente, {expressao} AS nome
                FROM dbo.entidade e
                WHERE e.{_optical_sql_name(cols['id_entidade'])}
                  IN ({placeholders})""", codigos)
            for registro in dados:
                nome = registro.get('nome')
                if nome is not None and str(nome).strip():
                    encontrados[registro['id_cliente']] = (
                        str(nome).strip(), 'cadastro_entidade')
    except DatabaseError:
        # Algumas copias do banco nao incluem a entidade ou a permissao.
        # Falhar aqui nao deve impedir a consulta historica principal.
        pass

    faltantes = [codigo for codigo in codigos if codigo not in encontrados]
    if faltantes:
        placeholders = ','.join('?' for _ in faltantes)
        try:
            dados = run(con, f"""WITH nomes AS (
                SELECT o.id_entidade_cliente AS id_cliente,
                    o.nome_cliente AS nome,
                    ROW_NUMBER() OVER (
                        PARTITION BY o.id_entidade_cliente
                        ORDER BY o.data_hora_cadastro DESC,
                                 o.id_ordem_servico DESC
                    ) AS pos
                FROM dbo.ordem_servico o
                WHERE o.id_entidade_cliente IN ({placeholders})
                  AND NULLIF(LTRIM(RTRIM(o.nome_cliente)), N'') IS NOT NULL
            )
            SELECT id_cliente, nome FROM nomes WHERE pos=1""", faltantes)
        except DatabaseError:
            dados = []
        for registro in dados:
            nome = registro.get('nome')
            if nome is not None and str(nome).strip():
                encontrados[registro['id_cliente']] = (
                    str(nome).strip(), 'outra_os')

    for registro in registros:
        codigo = registro.get('id_cliente')
        if codigo in encontrados and (
                registro.get(campo) is None or
                not str(registro.get(campo)).strip()):
            registro[campo], registro['cliente_origem'] = encontrados[codigo]
    return registros


